/**
 * POST with HTTP status preserved — for AI 402 credit checks.
 * Exception to apiClient-only rule: see mfe-setup-checklist.md §7.6 · ai-integration.md
 */
import {
  buildTenantRequestHeaders,
  getAuthToken,
  X_COMPANY_ID_HEADER,
} from '@linm-soft-org/linm-web-common-components';
import { readActiveCompanyIdForRequest } from '../../utils/activeCompanyValidate';

export async function postBffWithStatus<TJson>(
  endpoint: string,
  body: unknown,
  extraHeaders?: Record<string, string>,
): Promise<{ status: number; json: TJson }> {
  const baseURL =
    (import.meta.env.VITE_API_URL as string | undefined)?.replace(/\/$/, '') ??
    'http://localhost:5100/web-bff/api/v1';
  const headers = buildTenantRequestHeaders(extraHeaders);
  const token = getAuthToken();
  if (token) headers.Authorization = `Bearer ${token}`;

  const companyId = readActiveCompanyIdForRequest();
  if (companyId) headers[X_COMPANY_ID_HEADER] = companyId;

  const response = await fetch(`${baseURL}${endpoint}`, {
    method: 'POST',
    headers,
    body: JSON.stringify(body),
  });
  const json = (await response.json().catch(() => ({}))) as TJson;
  return { status: response.status, json };
}
