/**
 * Bảng dữ liệu Word — html-docx-js bỏ qua border-collapse (viền đôi + khe trắng).
 * SSOT: hop-dong-docx/panel-extract.mjs · timelessq html-docx table border
 */
import { DOCX_FONT } from './docxTypography';

const DATA_TABLE_SELECTOR = 'table[data-lin-docx-typo="table11"]';

const TABLE_BORDER_STYLE = [
  'border-collapse:collapse',
  'border-spacing:0',
  'width:100%',
  'border:1px solid #000',
  'margin-top:6px',
  'mso-table-lspace:0pt',
  'mso-table-rspace:0pt',
  DOCX_FONT,
  'font-size:11pt',
].join(';');

const TH_BORDER_STYLE = [
  DOCX_FONT,
  'font-size:11pt',
  'border:1px solid #000',
  'padding:5px 8px',
  'vertical-align:top',
  'font-weight:bold',
  'text-align:center',
].join(';');

const TD_BORDER_STYLE = [
  DOCX_FONT,
  'font-size:11pt',
  'border:1px solid #000',
  'padding:5px 8px',
  'vertical-align:top',
].join(';');

const CELL_PRESERVE = [
  'text-align',
  'vertical-align',
  'font-weight',
  'font-style',
  'color',
  'font-size',
  'font-family',
];

function extractPreserved(existing: string): string {
  const parts: string[] = [];
  for (const prop of CELL_PRESERVE) {
    const re = new RegExp(`${prop}\\s*:\\s*[^;]+`, 'i');
    const m = existing.match(re);
    if (m) parts.push(m[0].trim());
  }
  return parts.join(';');
}

function applyCellBorderStyle(el: HTMLElement, base: string): void {
  const preserved = extractPreserved(el.getAttribute('style') || '');
  el.setAttribute('style', preserved ? `${base};${preserved}` : base);
  el.removeAttribute('width');
}

/** Bảng có viền (§1/3/4) — cellspacing=0 + viền table + từng ô (Word). */
export function normalizeDocxDataTables(root: HTMLElement): void {
  root.querySelectorAll(DATA_TABLE_SELECTOR).forEach((node) => {
    if (!(node instanceof HTMLTableElement)) return;

    node.setAttribute('cellspacing', '0');
    node.setAttribute('cellpadding', '0');
    node.setAttribute('border', '1');
    node.setAttribute('style', TABLE_BORDER_STYLE);

    node.querySelectorAll('th').forEach((th) => {
      if (th instanceof HTMLElement) applyCellBorderStyle(th, TH_BORDER_STYLE);
    });
    node.querySelectorAll('td').forEach((td) => {
      if (td instanceof HTMLElement) applyCellBorderStyle(td, TD_BORDER_STYLE);
    });
  });
}

/** Bảng layout không viền (header / chữ ký) — tắt border Word mặc định. */
export function normalizeDocxLayoutTables(root: HTMLElement): void {
  root.querySelectorAll('table:not([data-lin-docx-typo="table11"])').forEach((node) => {
    if (!(node instanceof HTMLTableElement)) return;
    node.setAttribute('cellspacing', '0');
    node.setAttribute('cellpadding', '0');
    node.setAttribute('border', '0');
    node.querySelectorAll('td, th').forEach((cell) => {
      if (!(cell instanceof HTMLElement)) return;
      const prev = cell.getAttribute('style') || '';
      if (/border\s*:\s*none/i.test(prev)) return;
      if (!/border/i.test(prev)) {
        cell.setAttribute('style', prev ? `${prev};border:none` : 'border:none');
      }
    });
  });
}

export function normalizeDocxTables(root: HTMLElement): void {
  normalizeDocxDataTables(root);
  normalizeDocxLayoutTables(root);
}
