import React from 'react';
import { CHART_COLORS } from '../../MedicalIncidentReportPage/chartUtils';
import { ChartTypeSelector, DynamicChart } from './MonthlyReportEditorCharts';
import type { ChartDisplayType } from './monthlyReportEditorShared';
import s from './MonthlyReportEditor.module.css';

interface CountItem {
  key: string;
  label: string;
  count: number;
}

interface Props {
  visible: boolean;
  /** Mount Chart.js khi In/Preview dù không ở tab Mục 2. */
  forceChartsMount?: boolean;
  readOnly: boolean;
  activeTypeGroups: CountItem[];
  activeCauseGroups: CountItem[];
  ncGroups: CountItem[];
  typeGroupChartType: ChartDisplayType;
  occurrenceChartType: ChartDisplayType;
  causeGroupChartType: ChartDisplayType;
  typeGroupText: string;
  occurrenceText: string;
  causeGroupText: string;
  onChartTypeChange: (
    setter: React.Dispatch<React.SetStateAction<ChartDisplayType>>,
    value: ChartDisplayType,
  ) => void;
  setTypeGroupChartType: React.Dispatch<React.SetStateAction<ChartDisplayType>>;
  setOccurrenceChartType: React.Dispatch<React.SetStateAction<ChartDisplayType>>;
  setCauseGroupChartType: React.Dispatch<React.SetStateAction<ChartDisplayType>>;
  onAnalysisTextChange: (setter: React.Dispatch<React.SetStateAction<string>>, value: string) => void;
  setTypeGroupText: React.Dispatch<React.SetStateAction<string>>;
  setOccurrenceText: React.Dispatch<React.SetStateAction<string>>;
  setCauseGroupText: React.Dispatch<React.SetStateAction<string>>;
  captureTypeGroup: (b64: string) => void;
  captureOccurrence: (b64: string) => void;
  captureCauseGroup: (b64: string) => void;
}

export const MonthlyReportSectionAnalysis: React.FC<Props> = ({
  visible,
  forceChartsMount = false,
  readOnly,
  activeTypeGroups,
  activeCauseGroups,
  ncGroups,
  typeGroupChartType,
  occurrenceChartType,
  causeGroupChartType,
  typeGroupText,
  occurrenceText,
  causeGroupText,
  onChartTypeChange,
  setTypeGroupChartType,
  setOccurrenceChartType,
  setCauseGroupChartType,
  onAnalysisTextChange,
  setTypeGroupText,
  setOccurrenceText,
  setCauseGroupText,
  captureTypeGroup,
  captureOccurrence,
  captureCauseGroup,
}) => {
  const mountCharts = visible || forceChartsMount;

  return (
  <div
    id="monthly-report-section-analysis"
    className={visible ? undefined : s.sectionHidden}
    aria-hidden={!visible}
  >
    <div className={s.analysisSubsection}>
      <div className={s.analysisSubsectionHeader}>
        <div className={s.analysisSubsectionTitle}>
          <i className="fas fa-layer-group" style={{ color: CHART_COLORS[0] }} />
          2.1 Nhóm sự cố
          <span className={s.figLabel}>Hình 1</span>
        </div>
        <ChartTypeSelector
          disabled={readOnly}
          value={typeGroupChartType}
          onChange={(v) => onChartTypeChange(setTypeGroupChartType, v)}
        />
      </div>
      <div className={s.chartContainer}>
        {!mountCharts ? (
          <div className={s.chartEmpty}>Đang chuẩn bị biểu đồ...</div>
        ) : activeTypeGroups.length > 0 ? (
          <DynamicChart
            chartKey="typeGroup"
            type={typeGroupChartType}
            labels={activeTypeGroups.map((x) => x.label)}
            data={activeTypeGroups.map((x) => x.count)}
            onCapture={captureTypeGroup}
          />
        ) : (
          <div className={s.chartEmpty}>Không có dữ liệu nhóm sự cố</div>
        )}
      </div>
      <div className={s.analysisTextWrapper}>
        <label className={s.analysisTextLabel}>
          <i className="fas fa-pen-alt" /> Nhận xét phân tích (có thể chỉnh sửa)
        </label>
        <textarea
          className={s.analysisTextarea}
          rows={3}
          readOnly={readOnly}
          value={typeGroupText}
          onChange={(e) => onAnalysisTextChange(setTypeGroupText, e.target.value)}
          placeholder="Nhập nhận xét phân tích về nhóm sự cố..."
        />
      </div>
    </div>

    <div className={s.analysisSubsection}>
      <div className={s.analysisSubsectionHeader}>
        <div className={s.analysisSubsectionTitle}>
          <i className="fas fa-user-injured" style={{ color: CHART_COLORS[1] }} />
          2.2 Hậu quả đối với người bệnh
          <span className={s.figLabel}>Hình 2</span>
        </div>
        <ChartTypeSelector
          disabled={readOnly}
          value={occurrenceChartType}
          onChange={(v) => onChartTypeChange(setOccurrenceChartType, v)}
        />
      </div>
      <div className={s.chartContainer}>
        {!mountCharts ? (
          <div className={s.chartEmpty}>Đang chuẩn bị biểu đồ...</div>
        ) : ncGroups.length > 0 ? (
          <DynamicChart
            chartKey="occurrence"
            type={occurrenceChartType}
            labels={ncGroups.map((x) => x.label)}
            data={ncGroups.map((x) => x.count)}
            onCapture={captureOccurrence}
          />
        ) : (
          <div className={s.chartEmpty}>Không có dữ liệu hậu quả sự cố</div>
        )}
      </div>
      <div className={s.analysisTextWrapper}>
        <label className={s.analysisTextLabel}>
          <i className="fas fa-pen-alt" /> Nhận xét phân tích (có thể chỉnh sửa)
        </label>
        <textarea
          className={s.analysisTextarea}
          rows={3}
          readOnly={readOnly}
          value={occurrenceText}
          onChange={(e) => onAnalysisTextChange(setOccurrenceText, e.target.value)}
          placeholder="Nhập nhận xét phân tích về hậu quả sự cố..."
        />
      </div>
    </div>

    <div className={s.analysisSubsection}>
      <div className={s.analysisSubsectionHeader}>
        <div className={s.analysisSubsectionTitle}>
          <i className="fas fa-sitemap" style={{ color: CHART_COLORS[2] }} />
          2.3 Nhóm nguyên nhân gây ra sự cố
          <span className={s.figLabel}>Hình 3</span>
        </div>
        <ChartTypeSelector
          disabled={readOnly}
          value={causeGroupChartType}
          onChange={(v) => onChartTypeChange(setCauseGroupChartType, v)}
        />
      </div>
      <div className={s.chartContainer}>
        {!mountCharts ? (
          <div className={s.chartEmpty}>Đang chuẩn bị biểu đồ...</div>
        ) : activeCauseGroups.length > 0 ? (
          <DynamicChart
            chartKey="causeGroup"
            type={causeGroupChartType}
            labels={activeCauseGroups.map((x) => x.label)}
            data={activeCauseGroups.map((x) => x.count)}
            onCapture={captureCauseGroup}
          />
        ) : (
          <div className={s.chartEmpty}>Không có dữ liệu nhóm nguyên nhân</div>
        )}
      </div>
      <div className={s.analysisTextWrapper}>
        <label className={s.analysisTextLabel}>
          <i className="fas fa-pen-alt" /> Nhận xét phân tích (có thể chỉnh sửa)
        </label>
        <textarea
          className={s.analysisTextarea}
          rows={3}
          readOnly={readOnly}
          value={causeGroupText}
          onChange={(e) => onAnalysisTextChange(setCauseGroupText, e.target.value)}
          placeholder="Nhập nhận xét phân tích về nhóm nguyên nhân..."
        />
      </div>
    </div>
  </div>
  );
};
